#include HEADER
#include <chrono>
#include <cstdint>
#include <iostream>
#include <random>
#include <vector>
#include <cstdlib>
#include <string>
int main(int argc,char**argv){
 const int mode=std::atoi(argv[1]),kind=std::atoi(argv[2]);
 const int count=argc>3?std::atoi(argv[3]):65536;
 std::mt19937_64 rng(982763871);
 std::vector<Fraction>a,b;a.reserve(count);b.reserve(count);
 for(int i=0;i<count;++i){
  const auto n=std::int64_t(rng()%1000000)+1,m=std::int64_t(rng()%1000000)+1;
  const auto d=std::int64_t(rng()%1000000)+1,e=std::int64_t(rng()%1000000)+1;
  if(kind==0){a.emplace_back(n,d);b.emplace_back(m,e);}
  else if(kind==1){a.emplace_back(n,999983);b.emplace_back(m,999983);}
  else if(kind==2){a.emplace_back(n);b.emplace_back(m);}
  else if(kind==3){a.emplace_back(n,d);b.emplace_back(d,n);}
  else if(kind==4){a.emplace_back(n*1000000000,d*1000000000);b.emplace_back(-n*1000000000,d*1000000000);}
  else if(kind==5){a.emplace_back(n*9973,d*9973);b.emplace_back(m*9929,e*9929);}
  else if(kind==6){a.emplace_back(i%3==0?0:n,d);b.emplace_back(i%7==0?1:m,e);}
  else if(kind==7){const auto big=std::int64_t(rng()>>4)+1;a.emplace_back(big,2305843009213693951);b.emplace_back(std::int64_t(rng()>>4)+1,2305843009213693951);}
  else if(kind==8){const auto big=std::int64_t(rng()>>3)+1;a.emplace_back(big,big+1);b.emplace_back(big+1,big);}
  else if(kind==9){a.emplace_back(std::int64_t(rng()>>1));b.emplace_back(i%2?1:-1);}
  else if(kind==10){a.emplace_back(std::int64_t(rng()>>3),1000000007);b.emplace_back(std::int64_t(rng()>>3),1000000007);}
  else {a.emplace_back(n,std::int64_t{1000000000000}*997);b.emplace_back(m,std::int64_t{1000000000000}*991);}
 }
 std::uint64_t sum=0;
 const auto begin=std::chrono::steady_clock::now();
 for(int rep=0;rep<8;++rep)for(int i=0;i<count;++i){
  Fraction x;
  if(mode==0)x=a[i]+b[i];
  else if(mode==1)x=a[i]-b[i];
  else if(mode==2)x=a[i]*b[i];
  else if(mode==3)x=a[i]/b[i];
  else if(kind==8){x=a[i]*b[i];x/=b[i];}
  else if(kind>=7 && kind!=9){x=a[i]+b[i];x-=b[i];}
  else {x=a[i]+b[i];x-=b[i];x*=b[i];x/=b[i];}
  sum+=std::uint64_t(x.numerator())^std::uint64_t(x.denominator());
 }
 const auto ns=std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now()-begin).count();
 std::cout<<ns<<' '<<sum<<'\n';
}

