using Clock=std::chrono::steady_clock;
int main(int argc,char**argv){
 const std::string mode=argv[1]; const int n=std::atoi(argv[2]); const int reps=std::atoi(argv[3]);
 std::mt19937_64 rng(1674114);std::vector<std::array<Fraction,2>> v;v.reserve(n);
 for(int i=0;i<n;++i){
  auto val=[&](){if(mode=="full64")return Fraction(static_cast<std::int64_t>(rng()),static_cast<std::int64_t>((rng()>>1)|1));
   if(mode=="integer")return Fraction(static_cast<std::int64_t>(rng()));
   if(mode=="near")return Fraction(1000000000+i%9,1000000000+i%7);
   auto a=static_cast<std::int64_t>(rng()%1000000001),b=static_cast<std::int64_t>(rng()%1000000000+1);
   if(mode=="mixed" && (rng()&1))a=-a;
   if(mode=="negative")a=-a;
   return Fraction(a,b);};
  auto a=val(),b=val();if(mode=="equal")b=a;v.push_back({a,b});
 }
 const bool less_only = argc > 4 && std::string(argv[4]) == "less";
 std::int64_t checksum=0;auto start=Clock::now();
 for(int r=0;r<reps;++r){std::atomic_signal_fence(std::memory_order_acq_rel);if (less_only) {for(const auto& x:v) checksum += x[0] < x[1];}else{for(const auto& x:v){auto c=x[0]<=>x[1];checksum+=(c>0)-(c<0);}}}
 auto stop=Clock::now();std::cout<<std::chrono::duration<double,std::nano>(stop-start).count()/(n*double(reps))<<' '<<checksum<<'\n';
}

